import { ParameterSpecRecord } from "#base/scripts/voronoi-types.js";

import { RegionCell } from "../voronoi-utils.js";
import { Rule, ScoringContext } from "../voronoi_rules/rules-base.js";

const ruleSchema = {
	preferredNeighborCount: {
		label: "Preferred Neighbor Count",
		description:
			"The normal distribution used for scoring is centered on this value. Any cells with exactly this number of neighbors will score 1, everything else will be less than that.",
		default: 3,
		min: 0,
		max: 10,
		step: 0.1,
	},
	deviation: {
		label: "Preferred Neighbors Deviation",
		description:
			"The standard deviation for the normal distribution. Higher values will score number near the preferred count higher.",
		default: 1,
		min: 0,
		max: 5,
		step: 0.1,
	},
} as const satisfies ParameterSpecRecord;

export class RuleNeighborsInRegion extends Rule {
	override parameterSpecs = ruleSchema;
	override configValues = Rule.createDefaultsFromSpecs(ruleSchema);
	override name = RuleNeighborsInRegion.getName();
	override description = "Scores cells based on how many of their neighbors are already in the region";

	static getName(): string {
		return "Neighbors In Region";
	}

	static getSchema() {
		return ruleSchema;
	}

	// Can be replaced with custom logic.
	public inRegionCheck = (ctx: ScoringContext, _thisCell: RegionCell, neighborCell: RegionCell): boolean => {
		return ctx.region.getRegionIdForCell(neighborCell) === ctx.region.id;
	};

	score(regionCell: RegionCell, ctx: ScoringContext): number {
		let neighborCount = 0;
		for (const neighborId of regionCell.cell.getNeighborIds()) {
			const neighbor = ctx.cells[neighborId];
			if (this.inRegionCheck(ctx, regionCell, neighbor)) {
				neighborCount++;
			}
		}
		const x: number = neighborCount;
		const d: number = this.configValues.deviation;
		const m: number = this.configValues.preferredNeighborCount; // median

		// standard gaussian
		const zScore: number = (x - m) / d;
		const score: number = Math.exp(-0.5 * zScore * zScore);
		return score;
	}
}
